/**
 * Interactive driver for `apps/roam/scripts/playwright/loadExtension.ts --test-module`.
 *
 * Safety model (replaces the old "small HTTP server that evals snippets" pattern,
 * which exposed Node-side code execution on a TCP port any local process or web
 * page could POST to):
 * - Commands arrive over a Unix domain socket inside a 0700 directory owned by this
 *   user. There is no TCP port, so browsers and other users cannot reach it.
 * - Only the allowlisted actions below run. There is no Node-side eval. `evaluate`
 *   runs a string expression inside the Roam page's browser sandbox.
 *
 * Client example:
 *   curl -s --unix-socket /tmp/dg-roam-driver-$(id -u)/driver.sock \
 *     -H 'content-type: application/json' -d @cmd.json http://driver/
 */
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import type { BrowserContext, Page } from "playwright";

type HookOptions = { page: Page; context: BrowserContext; outDir: string };

type MouseButton = "left" | "right" | "middle";

type Command =
  | { action: "evaluate"; expression: string }
  | {
      action: "click";
      x: number;
      y: number;
      button?: MouseButton;
      clickCount?: number;
    }
  | { action: "move"; x: number; y: number; steps?: number }
  | { action: "down" | "up"; button?: MouseButton }
  | { action: "press"; key: string }
  | { action: "type"; text: string }
  | { action: "screenshot"; name: string; fullPage?: boolean }
  | { action: "viewport"; width: number; height: number }
  | { action: "wait"; ms: number }
  | { action: "console" }
  | { action: "done" };

const MAX_BODY_BYTES = 1_000_000;
const MAX_CONSOLE_MESSAGES = 200;
const SCREENSHOT_NAME = /^[\w-]{1,64}$/;
const BUTTONS = new Set(["left", "right", "middle"]);

const uid = typeof process.getuid === "function" ? process.getuid() : 0;
const SOCKET_DIR =
  process.env.DG_ROAM_DRIVER_DIR ||
  path.join(os.tmpdir(), `dg-roam-driver-${uid}`);
const SOCKET_PATH = path.join(SOCKET_DIR, "driver.sock");

const prepareSocketDir = (): void => {
