const isFiniteNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value);

const parseCommand = (raw: string): Command => {
  const value = JSON.parse(raw) as Record<string, unknown>;
  const action = value.action;
  const button = value.button;
  if (button !== undefined && !BUTTONS.has(button as string)) {
    throw new Error(`Invalid button: ${String(button)}`);
  }
  switch (action) {
    case "evaluate":
      if (typeof value.expression !== "string") break;
      return value as Command;
    case "click":
    case "move":
      if (!isFiniteNumber(value.x) || !isFiniteNumber(value.y)) break;
      return value as Command;
    case "down":
    case "up":
    case "console":
    case "done":
      return value as Command;
    case "press":
      if (typeof value.key !== "string") break;
      return value as Command;
    case "type":
      if (typeof value.text !== "string") break;
      return value as Command;
    case "screenshot":
      if (typeof value.name !== "string" || !SCREENSHOT_NAME.test(value.name)) {
        break;
      }
      return value as Command;
    case "viewport":
      if (!isFiniteNumber(value.width) || !isFiniteNumber(value.height)) break;
      return value as Command;
    case "wait":
      if (!isFiniteNumber(value.ms) || value.ms < 0 || value.ms > 60_000) break;
      return value as Command;
    default:
      throw new Error(`Unknown action: ${String(action)}`);
  }
  throw new Error(`Invalid arguments for action: ${String(action)}`);
};

const readBody = (req: http.IncomingMessage): Promise<string> =>
  new Promise((resolve, reject) => {
    let size = 0;
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error("Request body too large"));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });

export default {
  run: ({ page, outDir }: HookOptions): Promise<string> =>
    new Promise<string>((resolve, reject) => {
      const consoleMessages: string[] = [];
      page.on("console", (message) => {
        consoleMessages.push(`[${message.type()}] ${message.text()}`);
        if (consoleMessages.length > MAX_CONSOLE_MESSAGES) {
          consoleMessages.shift();
        }
      });
      page.on("pageerror", (error) => {
        consoleMessages.push(`[pageerror] ${error.message}`);
      });

      const execute = async (command: Command): Promise<unknown> => {
        switch (command.action) {
          case "evaluate":
            return page.evaluate(command.expression);
          case "click":
            return page.mouse.click(command.x, command.y, {
              button: command.button,
              clickCount: command.clickCount,
            });
          case "move":
            return page.mouse.move(command.x, command.y, {
              steps: command.steps,
            });
          case "down":
            return page.mouse.down({ button: command.button });
          case "up":
            return page.mouse.up({ button: command.button });
          case "press":
            return page.keyboard.press(command.key);
          case "type":
            return page.keyboard.type(command.text);
          case "screenshot": {
            const file = path.join(outDir, `${command.name}.png`);
            await page.screenshot({ path: file, fullPage: command.fullPage });
            return file;
          }
          case "viewport":
            return page.setViewportSize({
              width: command.width,
              height: command.height,
            });
          case "wait":
            return page.waitForTimeout(command.ms);
          case "console":
            return consoleMessages.splice(0, consoleMessages.length);
          case "done":
            return "done";
        }
      };

      const server = http.createServer((req, res) => {
        const respond = (status: number, payload: unknown): void => {
          res.writeHead(status, { "content-type": "application/json" });
          res.end(JSON.stringify(payload, null, 2));
        };
        if (
          req.method !== "POST" ||
          !req.headers["content-type"]?.startsWith("application/json")
        ) {
          respond(415, { ok: false, error: "POST application/json only" });
          return;
        }
        readBody(req)
          .then(parseCommand)
          .then(async (command) => {
            const value = await execute(command);
            respond(200, { ok: true, value: value ?? null });
            if (command.action === "done") {
              server.close();
              fs.rmSync(SOCKET_PATH, { force: true });
              resolve("done");
            }
          })
          .catch((error: unknown) => {
            respond(400, {
              ok: false,
              error: error instanceof Error ? error.message : String(error),
            });
          });
      });

      try {
        prepareSocketDir();
      } catch (error) {
        reject(error);
        return;
      }
      server.on("error", reject);
      server.listen(SOCKET_PATH, () => {
        fs.chmodSync(SOCKET_PATH, 0o600);
        console.log(`DG ROAM DRIVER READY ${SOCKET_PATH}`);
      });
    }),
};

