import fs from "node:fs/promises";
import type { Action } from "../recorder/recordDemo";

export type StepSource = "plan" | "model" | "you";

export type Step = {
  id: string;
  do: Action;
  why: string;
  source?: StepSource;
  approved?: boolean;
};

export type Verdict = "pass" | "fail" | "skip";

export type Expectation = { js?: string; text?: string };

export type CaseResult = {
  verdict: Verdict;
  at: string;
  session: string;
  note?: string;
};

export type TestCase = {
  id: string;
  title: string;
  intent?: string;
  steps: Step[];
  expect?: Expectation;
  notes?: string[];
  last?: CaseResult;
};

export type PlanTarget = {
  slot?: "1" | "2" | "3";
  url?: string;
  dist?: string;
  viewport?: { width: number; height: number };
  dpr?: number;
};

export type Plan = {
  name: string;
  title?: string;
  target?: PlanTarget;
  setup?: Step[];
  cases: TestCase[];
};

export const ACTION_KINDS = [
  "click",
  "type",
  "fill",
  "press",
  "hover",
  "scroll",
  "pause",
  "wait_for",
  "open",
  "js",
  "screenshot",
  "drag",
  "command_palette",
] as const;

export const SCREENSHOT_NAME = /^[\w.-]{1,80}$/;

const STEP_SOURCES: StepSource[] = ["plan", "model", "you"];
const MOUSE_BUTTONS = ["left", "right", "middle"];

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isText = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0;

const isNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value);

const isPoint = (value: unknown): boolean =>
  isRecord(value) && isNumber(value.x) && isNumber(value.y);

const optional = (value: unknown, check: (v: unknown) => boolean): boolean =>
  value === undefined || check(value);

const isAccepted = (kind: string, arg: unknown): boolean => {
  switch (kind) {
    case "click":
      return (
        isText(arg) ||
        (isRecord(arg) &&
          isText(arg.selector) &&
          optional(arg.button, (v) => MOUSE_BUTTONS.includes(v as string)) &&
          optional(arg.count, isNumber) &&
          optional(arg.position, isPoint))
      );
    case "type":
      return (
        isRecord(arg) &&
        isText(arg.into) &&
        typeof arg.text === "string" &&
        optional(arg.delay_ms, isNumber)
      );
    case "fill":
      return isRecord(arg) && isText(arg.into) && typeof arg.text === "string";
    case "press":
      return (
        isText(arg) ||
        (isRecord(arg) && isText(arg.key) && optional(arg.selector, isText))
      );
    case "hover":
    case "wait_for":
    case "open":
    case "js":
      return isText(arg);
    case "scroll":
      return (
        isNumber(arg) ||
        (isRecord(arg) && optional(arg.y, isNumber) && optional(arg.to, isText))
      );
    case "pause":
      return isNumber(arg) && arg >= 0 && arg <= 60;
    case "screenshot":
      return typeof arg === "string" && SCREENSHOT_NAME.test(arg);
    case "drag":
      return (
        isRecord(arg) &&
        isText(arg.from) &&
        isText(arg.to) &&
        optional(arg.hover, isText) &&
        optional(arg.hoverAt, (v) => v === "center" || v === "end") &&
        optional(arg.toPosition, isPoint)
      );
    case "command_palette":
      return (
        isText(arg) ||
        (isRecord(arg) &&
          isText(arg.label) &&
          optional(arg.type_delay_ms, isNumber))
      );
    default:
      return false;
  }
};

const EXPECTED_SHAPE: Record<string, string> = {
  click: "a selector or { selector, button?, count?, position? }",
  type: "{ into, text, delay_ms? }",
  fill: "{ into, text }",
  press: "a key or { selector?, key }",
  hover: "a selector",
  wait_for: "a selector",
  open: "a URL or path",
  js: "a JS expression",
  scroll: "a number or { y?, to? }",
  pause: "seconds from 0 to 60",
  screenshot: "a file name with no slashes",
  drag: "{ from, to, hover?, hoverAt?, toPosition? }",
  command_palette: "a label or { label, type_delay_ms? }",
};

export const validateAction = (value: unknown, where: string): Action => {
  if (!isRecord(value)) {
    throw new Error(`${where}: an action must be an object.`);
  }
  const keys = Object.keys(value);
  if (keys.length !== 1) {
    throw new Error(
      `${where}: an action has exactly one key, got ${keys.join(", ") || "none"}.`,
    );
  }
  const kind = keys[0];
  if (!(ACTION_KINDS as readonly string[]).includes(kind)) {
    throw new Error(
      `${where}: unknown action "${kind}". Known: ${ACTION_KINDS.join(", ")}.`,
    );
  }
  if (!isAccepted(kind, value[kind])) {
    throw new Error(`${where}: ${kind} expects ${EXPECTED_SHAPE[kind]}.`);
  }
  return value as Action;
};

export const nextStepId = (steps: Step[]): string => {
  const used = new Set(steps.map((step) => step.id));
  let index = steps.length + 1;
  while (used.has(`s${index}`)) index += 1;
  return `s${index}`;
};

export const validateStep = (
  value: unknown,
  where: string,
  existing: Step[],
  sourceOverride?: StepSource,
): Step => {
  if (!isRecord(value)) {
    throw new Error(`${where}: a step must be an object.`);
  }
  const action = validateAction(value.do, `${where}.do`);
  if (!isText(value.why)) {
    throw new Error(`${where}: every step needs a one-line "why".`);
  }
  const source = sourceOverride ?? value.source ?? "plan";
  if (!STEP_SOURCES.includes(source as StepSource)) {
    throw new Error(`${where}: source must be plan, model or you.`);
  }
  const id =
    isText(value.id) && !existing.some((step) => step.id === value.id)
      ? value.id
      : nextStepId(existing);
  const step: Step = {
    id,
    do: action,
    why: value.why.trim(),
    source: source as StepSource,
  };
  if (value.approved === true && sourceOverride === undefined) {
    step.approved = true;
  }
  return step;
};

export const validateSteps = (
  value: unknown,
  where: string,
  existing: Step[] = [],
  sourceOverride?: StepSource,
): Step[] => {
  if (!Array.isArray(value)) {
    throw new Error(`${where}: steps must be an array.`);
  }
  const steps: Step[] = [];
  value.forEach((raw, index) => {
    steps.push(
      validateStep(
        raw,
        `${where}[${index}]`,
        [...existing, ...steps],
        sourceOverride,
      ),
    );
  });
  return steps;
};

const validateExpectation = (
  value: unknown,
  where: string,
): Expectation | undefined => {
  if (value === undefined) return undefined;
  if (!isRecord(value)) {
    throw new Error(`${where}: expect must be an object with js and/or text.`);
  }
  const expectation: Expectation = {};
  if (value.js !== undefined) {
    if (!isText(value.js)) throw new Error(`${where}.js must be a string.`);
    expectation.js = value.js;
  }
  if (value.text !== undefined) {
    if (!isText(value.text)) throw new Error(`${where}.text must be a string.`);
    expectation.text = value.text;
  }
  return expectation.js || expectation.text ? expectation : undefined;
};

export const validateCase = (
  value: unknown,
  where: string,
  takenIds: Set<string>,
  fallbackId: string,
  sourceOverride?: StepSource,
): TestCase => {
  if (!isRecord(value)) {
    throw new Error(`${where}: a case must be an object.`);
  }
  const id = isText(value.id) ? value.id : fallbackId;
  if (takenIds.has(id)) {
    throw new Error(`${where}: duplicate case id "${id}".`);
  }
  if (!isText(value.title)) {
    throw new Error(`${where}: a case needs a "title".`);
  }
  const steps =
    value.steps === undefined
      ? []
      : validateSteps(value.steps, `${where}.steps`, [], sourceOverride);
  if (steps.length === 0 && !isText(value.intent)) {
    throw new Error(
      `${where}: a case needs steps, or an "intent" the brain can work from.`,
    );
  }
  const testCase: TestCase = { id, title: value.title.trim(), steps };
  if (isText(value.intent)) testCase.intent = value.intent.trim();
  const expectation = validateExpectation(value.expect, `${where}.expect`);
  if (expectation) testCase.expect = expectation;
  if (Array.isArray(value.notes)) {
    testCase.notes = value.notes.filter(isText);
  }
  if (isRecord(value.last) && typeof value.last.verdict === "string") {
    testCase.last = value.last as CaseResult;
  }
  return testCase;
};

const validateTarget = (value: unknown): PlanTarget | undefined => {
  if (value === undefined) return undefined;
  if (!isRecord(value)) throw new Error("target must be an object.");
  const target: PlanTarget = {};
  if (value.slot !== undefined) {
    if (!["1", "2", "3"].includes(String(value.slot))) {
      throw new Error("target.slot must be 1, 2 or 3.");
    }
    target.slot = String(value.slot) as PlanTarget["slot"];
  }
  if (isText(value.url)) target.url = value.url;
  if (isText(value.dist)) target.dist = value.dist;
  if (value.viewport !== undefined) {
    const viewport = value.viewport;
    if (
      !isRecord(viewport) ||
      !isNumber(viewport.width) ||
      !isNumber(viewport.height)
    ) {
      throw new Error("target.viewport must be { width, height }.");
    }
    target.viewport = { width: viewport.width, height: viewport.height };
  }
  if (value.dpr !== undefined) {
    if (!isNumber(value.dpr) || value.dpr <= 0) {
      throw new Error("target.dpr must be a positive number.");
    }
    target.dpr = value.dpr;
  }
  return target;
};

export const validatePlan = (value: unknown): Plan => {
  if (!isRecord(value)) throw new Error("A plan must be a JSON object.");
  if (!isText(value.name)) throw new Error('A plan needs a "name".');
  if (!Array.isArray(value.cases) || value.cases.length === 0) {
    throw new Error('A plan needs at least one case in "cases".');
  }
  const takenIds = new Set<string>();
  const cases = value.cases.map((raw, index) => {
    const testCase = validateCase(
      raw,
      `cases[${index}]`,
      takenIds,
      `c${index + 1}`,
    );
    takenIds.add(testCase.id);
    return testCase;
  });
  const plan: Plan = { name: value.name.trim(), cases };
  if (isText(value.title)) plan.title = value.title.trim();
  const target = validateTarget(value.target);
  if (target) plan.target = target;
  if (value.setup !== undefined) {
    plan.setup = validateSteps(value.setup, "setup");
  }
  return plan;
};

export const loadPlan = async (file: string): Promise<Plan> => {
  const raw = await fs.readFile(file, "utf8");
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(`${file} is not valid JSON: ${String(error)}`);
  }
  return validatePlan(parsed);
};

export const savePlan = async (file: string, plan: Plan): Promise<void> => {
  await fs.writeFile(file, `${JSON.stringify(plan, null, 2)}\n`);
};

import fs from "node:fs";

export type JournalEvent = {
  seq: number;
  t: number;
  type: string;
  [key: string]: unknown;
};

// Append-only event log for one rehearsal. Every event is written to disk as
// it happens (JSONL), so a killed session still leaves its record, and kept in
// memory so the brain can long-poll for what's new.
export class Journal {
  private readonly events: JournalEvent[] = [];
  private waiters: Array<() => void> = [];
  private seq = 0;

  constructor(private readonly file: string | null) {}

  append(type: string, payload: Record<string, unknown> = {}): JournalEvent {
    this.seq += 1;
    const event: JournalEvent = {
      ...payload,
      seq: this.seq,
      t: Date.now(),
      type,
    };
    this.events.push(event);
    if (this.file) fs.appendFileSync(this.file, `${JSON.stringify(event)}\n`);
    const waiters = this.waiters;
    this.waiters = [];
    for (const wake of waiters) wake();
    return event;
  }

  get lastSeq(): number {
    return this.seq;
  }

  all(): JournalEvent[] {
    return [...this.events];
  }

  since(seq: number): JournalEvent[] {
    return this.events.filter((event) => event.seq > seq);
  }

  async wait(seq: number, timeoutMs: number): Promise<JournalEvent[]> {
    const ready = this.since(seq);
    if (ready.length > 0 || timeoutMs <= 0) return ready;
    await new Promise<void>((resolve) => {
      const timer = setTimeout(resolve, timeoutMs);
      this.waiters.push(() => {
        clearTimeout(timer);
        resolve();
      });
    });
    return this.since(seq);
  }
}

import type { Action } from "../recorder/recordDemo";
import type { Journal } from "./journal";
import {
  validateCase,
  validateSteps,
  type Plan,
  type Step,
  type StepSource,
  type TestCase,
  type Verdict,
} from "./plan";

export type Mode = "auto" | "step" | "case";

export type Phase =
  | "starting"
  | "running"
  | "dwell"
  | "paused"
  | "waiting-next"
  | "waiting-steps"
  | "waiting-approval"
  | "waiting-verdict"
  | "step-failed"
  | "done"
  | "stopped";

// The HUD is the person at the screen; the socket is the brain. Only the HUD
// can approve model-written js or give a final verdict.
export type CommandSource = "hud" | "socket";

export type Pending =
  | { kind: "steps"; caseId: string; reason: string }
  | { kind: "failure"; caseId: string | null; stepId: string; error: string }
  | {
      kind: "approval";
      caseId: string | null;
      stepId: string;
      js: string;
      why: string;
    }
  | {
      kind: "verdict";
      caseId: string;
      text: string;
      proposal?: { verdict: Verdict; reason?: string };
    };

export type MachineState = {
  phase: Phase;
  mode: Mode;
  speed: number;
  dwellMs: number;
  paused: boolean;
  executing: boolean;
  caseIndex: number;
  caseCount: number;
  caseId: string | null;
  caseTitle: string | null;
  stepIndex: number;
  stepCount: number;
  stepWhy: string | null;
  stepSource: StepSource | null;
  pending: Pending | null;
  results: Record<string, Verdict>;
};

export type Executor = {
  run(action: Action): Promise<void>;
  check(js: string): Promise<void>;
  snapshot(): Promise<string>;
  render(state: MachineState): Promise<void>;
};

export type CommandResult =
  | { ok: true; value?: unknown }
  | { ok: false; error: string };

export type CaseOutcome = { verdict: Verdict; note?: string };

export const SPEEDS = [0.25, 0.5, 1, 1.5, 2, 3, 4];

export const MIN_SPEED = SPEEDS[0];
export const MAX_SPEED = SPEEDS[SPEEDS.length - 1];

const STEP_HOW = [
  "append",
  "insert-next",
  "replace-rest",
  "replace-failed",
] as const;

type StepHow = (typeof STEP_HOW)[number];

const describe = (error: unknown): string =>
  (error instanceof Error ? error.message : String(error)).slice(0, 800);

const nextCaseId = (cases: TestCase[]): string => {
  const used = new Set(cases.map((testCase) => testCase.id));
  let index = cases.length + 1;
  while (used.has(`c${index}`)) index += 1;
  return `c${index}`;
};

export const scaleAction = (action: Action, speed: number): Action => {
  if (speed === 1) return action;
  if ("pause" in action) return { pause: action.pause / speed };
  if ("type" in action) {
    return {
      type: {
        ...action.type,
        delay_ms: Math.round((action.type.delay_ms ?? 50) / speed),
      },
    };
  }
  if ("command_palette" in action) {
    const value = action.command_palette;
    const label = typeof value === "string" ? value : value.label;
    const delay = typeof value === "string" ? 60 : (value.type_delay_ms ?? 60);
    return {
      command_palette: { label, type_delay_ms: Math.round(delay / speed) },
    };
  }
  return action;
};

export type MachineOptions = {
  plan: Plan;
  journal: Journal;
  executor: Executor;
  mode?: Mode;
  speed?: number;
  dwellMs?: number;
  // Steps that arrive over the socket may only `open` URLs on this origin.
  origin?: string;
  // After the last case, wait for added cases or an explicit stop.
  stayOpen?: boolean;
  // Runs each time every case has a verdict, e.g. to write an interim bake.
  onIdle?: () => Promise<void>;
};

export class Machine {
  readonly plan: Plan;
  private readonly journal: Journal;
  private readonly executor: Executor;
  private readonly origin?: string;
  private readonly stayOpen: boolean;
  private readonly onIdle?: () => Promise<void>;

  private mode: Mode;
  private speed: number;
  private dwellMs: number;
  private phase: Phase = "starting";
  private paused = false;
  private executing = false;
  private caseIndex = -1;
  private stepIndex = 0;
  private cursor = 0;
  private pending: Pending | null = null;
  private readonly verdicts: Record<string, Verdict> = {};
  private readonly verdictNotes: Record<string, string> = {};

  private wakers: Array<() => void> = [];
  private renderChain: Promise<void> = Promise.resolve();

  private stepOnce = false;
  private skipDwell = false;
  private stopRequested = false;
  private skipCaseRequested = false;
  private forcedVerdict: CaseOutcome | null = null;
  private failureResolution: "retry" | "skip" | "replaced" | null = null;
  private approval: "allow" | "deny" | null = null;
  private humanVerdict: CaseOutcome | null = null;

  constructor(options: MachineOptions) {
    this.plan = options.plan;
    this.journal = options.journal;
    this.executor = options.executor;
    this.origin = options.origin;
    this.stayOpen = options.stayOpen ?? false;
    this.onIdle = options.onIdle;
    this.mode = options.mode ?? "auto";
    this.speed = options.speed ?? 1;
    this.dwellMs = options.dwellMs ?? 1200;
  }

  get results(): Record<string, Verdict> {
    return { ...this.verdicts };
  }

  get notes(): Record<string, string> {
    return { ...this.verdictNotes };
  }

  state(): MachineState {
    const testCase = this.currentCase();
    const steps = this.currentSteps();
    const step = steps[this.stepIndex];
    return {
      phase: this.phase,
      mode: this.mode,
      speed: this.speed,
      dwellMs: this.dwellMs,
      paused: this.paused,
      executing: this.executing,
      caseIndex: this.caseIndex,
      caseCount: this.plan.cases.length,
      caseId: testCase?.id ?? null,
      caseTitle: testCase?.title ?? (this.caseIndex < 0 ? "Setup" : null),
      stepIndex: this.stepIndex,
      stepCount: steps.length,
      stepWhy: step?.why ?? null,
      stepSource: step?.source ?? null,
      pending: this.pending,
      results: { ...this.verdicts },
    };
  }

  status(): Record<string, unknown> {
    return {
      ...this.state(),
      cases: this.plan.cases.map((testCase, index) => ({
        id: testCase.id,
        title: testCase.title,
        intent: testCase.intent ?? null,
        expect: testCase.expect ?? null,
        current: index === this.caseIndex,
        verdict: this.verdicts[testCase.id] ?? null,
        steps: testCase.steps.map((step) => ({
          id: step.id,
          why: step.why,
          source: step.source ?? "plan",
          do: step.do,
        })),
      })),
    };
  }

  command(
    source: CommandSource,
    cmd: string,
    args: Record<string, unknown> = {},
  ): CommandResult {
    try {
      const value = this.apply(source, cmd, args);
      this.wake();
      void this.render();
      return { ok: true, value };
    } catch (error) {
      return { ok: false, error: describe(error) };
    }
  }

  stop(): void {
    this.command("socket", "stop");
  }

  async run(): Promise<void> {
    this.log("session-start", {
      plan: this.plan.name,
      mode: this.mode,
      speed: this.speed,
      cases: this.plan.cases.map(({ id, title }) => ({ id, title })),
    });
    if (this.plan.setup?.length) {
      this.caseIndex = -1;
      this.log("setup-start", { stepCount: this.plan.setup.length });
      const finished = await this.runSteps(null, this.plan.setup);
      this.skipCaseRequested = false;
      this.log("setup-end", { finished });
    }
    let index = 0;
    while (!this.stopRequested) {
      if (index < this.plan.cases.length) {
        this.caseIndex = index;
        await this.runCase(this.plan.cases[index]);
        index += 1;
        if (this.mode === "case" && index < this.plan.cases.length) {
          this.paused = true;
        }
        continue;
      }
      this.caseIndex = this.plan.cases.length;
      this.stepIndex = 0;
      this.setPhase("done");
      this.log("plan-done", { results: { ...this.verdicts } });
      if (this.onIdle) await this.onIdle();
      if (!this.stayOpen) break;
      while (!this.stopRequested && index >= this.plan.cases.length) {
        await this.signal();
      }
    }
    this.setPhase(this.stopRequested ? "stopped" : "done");
    this.log("session-end", {
      results: { ...this.verdicts },
      stopped: this.stopRequested,
    });
    await this.renderChain;
  }

  private apply(
    source: CommandSource,
    cmd: string,
    args: Record<string, unknown>,
  ): unknown {
    switch (cmd) {
      case "hello":
        return this.state();
      case "status":
        return this.status();
      case "pause":
        this.paused = true;
        this.log("paused", { by: source });
        return this.state();
      case "resume":
        this.paused = false;
        this.log("resumed", { by: source });
        return this.state();
      case "next":
        this.stepOnce = true;
        this.skipDwell = true;
        return this.state();
      case "mode": {
        const mode = args.mode;
        if (mode !== "auto" && mode !== "step" && mode !== "case") {
          throw new Error("mode must be auto, step or case.");
        }
        this.mode = mode;
        this.log("mode", { mode, by: source });
        return this.state();
      }
      case "speed": {
        const speed = Number(args.speed);
        if (!Number.isFinite(speed) || speed < MIN_SPEED || speed > MAX_SPEED) {
          throw new Error(`speed must be between ${MIN_SPEED} and ${MAX_SPEED}.`);
        }
        this.speed = speed;
        this.log("speed", { speed, by: source });
        return this.state();
      }
      case "dwell": {
        const ms = Number(args.ms);
        if (!Number.isFinite(ms) || ms < 0 || ms > 10_000) {
          throw new Error("dwell ms must be between 0 and 10000.");
        }
        this.dwellMs = ms;
        this.log("dwell", { ms, by: source });
        return this.state();
      }
      case "skip-step": {
        if (this.pending?.kind === "failure") {
          this.failureResolution = "skip";
          return this.state();
        }
        if (this.pending?.kind === "approval") {
          this.approval = "deny";
          return this.state();
        }
        throw new Error(
          "Nothing to skip: skip-step works on a failed step or one waiting for approval.",
        );
      }
      case "skip-case": {
        const testCase = this.currentCase();
        if (!testCase) throw new Error("No case is running.");
        this.skipCaseRequested = true;
        this.log("skip-case", { caseId: testCase.id, by: source });
        return this.state();
      }
      case "retry":
        if (this.pending?.kind !== "failure") {
          throw new Error("No failed step to retry.");
        }
        this.failureResolution = "retry";
        return this.state();
      case "steps":
        return this.receiveSteps(source, args);
      case "add-case":
        return this.addCase(source, args);
      case "approve":
      case "deny": {
        if (source !== "hud") {
          throw new Error("Only the HUD can approve or deny a step.");
        }
        const pending = this.pending;
        if (pending?.kind !== "approval" || pending.stepId !== args.stepId) {
          throw new Error("No step with that id is waiting for approval.");
        }
        this.approval = cmd === "approve" ? "allow" : "deny";
        return this.state();
      }
      case "verdict":
        return this.receiveVerdict(source, args);
      case "note": {
        const text = typeof args.text === "string" ? args.text.trim() : "";
        if (!text) throw new Error("A note needs text.");
        this.log("note", {
          caseId:
            typeof args.caseId === "string"
              ? args.caseId
              : (this.currentCase()?.id ?? null),
          text: text.slice(0, 2000),
          by: source === "hud" ? "you" : args.by === "you" ? "you" : "model",
        });
        return this.state();
      }
      case "stop":
        if (!this.stopRequested) {
          this.stopRequested = true;
          this.log("stop-requested", { by: source });
        }
        return this.state();
      default:
        throw new Error(`Unknown command "${cmd}".`);
    }
  }

  private receiveSteps(
    source: CommandSource,
    args: Record<string, unknown>,
  ): unknown {
    const how = (args.how ?? "append") as StepHow;
    if (!STEP_HOW.includes(how)) {
      throw new Error(`how must be one of ${STEP_HOW.join(", ")}.`);
    }
    const testCase =
      typeof args.caseId === "string"
        ? this.findCase(args.caseId)
        : this.currentCase();
    if (!testCase) throw new Error("No such case is running.");
    const by: StepSource =
      source === "hud" || args.by === "you" ? "you" : "model";
    const steps = validateSteps(args.steps, "steps", testCase.steps, by);
    if (steps.length === 0) throw new Error("Send at least one step.");
    for (const step of steps) this.checkOrigin(step);

    const isCurrent = testCase === this.currentCase();
    const list = testCase.steps;
    if (how === "append") {
      list.push(...steps);
    } else if (how === "insert-next") {
      const at = isCurrent ? Math.min(this.cursor, list.length) : list.length;
      list.splice(at, 0, ...steps);
    } else if (how === "replace-rest") {
      const from = isCurrent ? Math.min(this.cursor, list.length) : 0;
      list.splice(from, list.length - from, ...steps);
    } else {
      const pending = this.pending;
      if (pending?.kind !== "failure" || !isCurrent) {
        throw new Error("No failed step to replace.");
      }
      const index = list.findIndex((step) => step.id === pending.stepId);
      if (index < 0) throw new Error("The failed step is no longer in the case.");
      list.splice(index, 1, ...steps);
      this.failureResolution = "replaced";
    }
    this.log("steps-added", { caseId: testCase.id, how, by, steps });
    return { caseId: testCase.id, stepIds: steps.map((step) => step.id) };
  }

  private addCase(source: CommandSource, args: Record<string, unknown>): unknown {
    const by: StepSource =
      source === "hud" || args.by === "you" ? "you" : "model";
    const taken = new Set(this.plan.cases.map((testCase) => testCase.id));
    const testCase = validateCase(
      args.case,
      "case",
      taken,
      nextCaseId(this.plan.cases),
      by,
    );
    for (const step of testCase.steps) this.checkOrigin(step);
    this.plan.cases.push(testCase);
    this.log("case-added", { caseId: testCase.id, title: testCase.title, by });
    return { caseId: testCase.id };
  }

  private receiveVerdict(
    source: CommandSource,
    args: Record<string, unknown>,
  ): unknown {
    const verdict = args.verdict;
    if (verdict !== "pass" && verdict !== "fail") {
      throw new Error('verdict must be "pass" or "fail".');
    }
    const rawNote = typeof args.note === "string" ? args.note : args.reason;
    const note =
      typeof rawNote === "string" && rawNote.trim()
        ? rawNote.trim().slice(0, 1000)
        : undefined;
    const pending = this.pending;
    if (source === "socket") {
      if (pending?.kind !== "verdict") {
        throw new Error("No case is waiting for a verdict.");
      }
      pending.proposal = { verdict, reason: note };
      this.log("verdict-proposed", { caseId: pending.caseId, verdict, reason: note });
      return this.state();
    }
    if (pending?.kind === "verdict") {
      this.humanVerdict = { verdict, note };
      return this.state();
    }
    const testCase = this.currentCase();
    if (!testCase) throw new Error("No case is running.");
    this.forcedVerdict = { verdict, note };
    this.skipCaseRequested = true;
    this.log("verdict-forced", { caseId: testCase.id, verdict, note });
    return this.state();
  }

  private checkOrigin(step: Step): void {
    if (!this.origin || !("open" in step.do)) return;
    const target = new URL(step.do.open, this.origin);
    if (target.origin !== this.origin) {
      throw new Error(`open must stay on ${this.origin}.`);
    }
  }

  private async runCase(testCase: TestCase): Promise<void> {
    this.skipCaseRequested = false;
    this.forcedVerdict = null;
    this.stepIndex = 0;
    this.cursor = 0;
    this.log("case-start", {
      caseId: testCase.id,
      title: testCase.title,
      intent: testCase.intent ?? null,
      stepCount: testCase.steps.length,
    });
    await this.holdWhilePaused();
    if (!this.interrupted() && testCase.steps.length === 0) {
      await this.waitForSteps(testCase, "no-steps");
    }
    const finished =
      !this.interrupted() && (await this.runSteps(testCase, testCase.steps));
    if (this.stopRequested && !this.forcedVerdict) {
      this.log("case-interrupted", { caseId: testCase.id });
      return;
    }
    let outcome: CaseOutcome | null;
    if (this.forcedVerdict) outcome = this.forcedVerdict;
    else if (!finished) outcome = { verdict: "skip" };
    else outcome = await this.judge(testCase);
    if (!outcome) {
      if (this.stopRequested) {
        this.log("case-interrupted", { caseId: testCase.id });
        return;
      }
      outcome = this.forcedVerdict ?? { verdict: "skip" };
    }
    this.verdicts[testCase.id] = outcome.verdict;
    if (outcome.note) this.verdictNotes[testCase.id] = outcome.note;
    this.log("case-end", {
      caseId: testCase.id,
      verdict: outcome.verdict,
      note: outcome.note ?? null,
    });
    this.skipCaseRequested = false;
    this.forcedVerdict = null;
  }

  private async runSteps(
    testCase: TestCase | null,
    steps: Step[],
  ): Promise<boolean> {
    for (let index = 0; index < steps.length; index += 1) {
      this.stepIndex = index;
      this.cursor = index;
      await this.gate();
      if (this.interrupted()) return false;
      const step = steps[index];
      if (this.needsApproval(step)) {
        const allowed = await this.waitForApproval(testCase, step);
        if (this.interrupted()) return false;
        if (!allowed) {
          steps.splice(index, 1);
          index -= 1;
          continue;
        }
        step.approved = true;
      }
      this.cursor = index + 1;
      const outcome = await this.execute(testCase, step);
      if (this.interrupted()) return false;
      if (outcome === "retry" || outcome === "replaced") {
        index -= 1;
        continue;
      }
      await this.dwell();
    }
    return true;
  }

  private needsApproval(step: Step): boolean {
    return "js" in step.do && (step.source ?? "plan") !== "plan" && !step.approved;
  }

  private async gate(): Promise<void> {
    for (;;) {
      if (this.interrupted()) return;
      if (this.stepOnce) {
        this.stepOnce = false;
        return;
      }
      if (this.paused) {
        this.setPhase("paused");
        await this.signal();
        continue;
      }
      if (this.mode === "step") {
        this.setPhase("waiting-next");
        await this.signal();
        continue;
      }
      return;
    }
  }

  private async holdWhilePaused(): Promise<void> {
    while (this.paused && !this.interrupted()) {
      if (this.stepOnce) {
        this.stepOnce = false;
        return;
      }
      this.setPhase("paused");
      await this.signal();
    }
  }

  private async dwell(): Promise<void> {
    const ms = this.dwellMs / this.speed;
    this.skipDwell = false;
    if (ms <= 0) return;
    const until = Date.now() + ms;
    this.setPhase("dwell");
    while (
      Date.now() < until &&
      !this.skipDwell &&
      !this.paused &&
      !this.interrupted()
    ) {
      await this.signal(until - Date.now());
    }
    this.skipDwell = false;
  }

  private async execute(
    testCase: TestCase | null,
    step: Step,
  ): Promise<"ok" | "skip" | "retry" | "replaced"> {
    const ids = { caseId: testCase?.id ?? null, stepId: step.id };
    this.executing = true;
    this.setPhase("running");
    this.log("step-start", {
      ...ids,
      why: step.why,
      source: step.source ?? "plan",
      do: step.do,
    });
    try {
      await this.executor.run(scaleAction(step.do, this.speed));
      this.executing = false;
      this.log("step-done", ids);
      return "ok";
    } catch (error) {
      this.executing = false;
      const message = describe(error);
      const aria = await this.snapshot();
      this.pending = {
        kind: "failure",
        caseId: ids.caseId,
        stepId: step.id,
        error: message,
      };
      this.failureResolution = null;
      this.setPhase("step-failed");
      this.log("step-failed", { ...ids, why: step.why, error: message, aria });
      while (!this.failureResolution && !this.interrupted()) {
        await this.signal();
      }
      const resolution = this.failureResolution ?? "skip";
      this.failureResolution = null;
      this.pending = null;
      this.log("step-resolved", { ...ids, resolution });
      return resolution;
    } finally {
      this.executing = false;
      void this.render();
    }
  }

  private async waitForSteps(testCase: TestCase, reason: string): Promise<void> {
    const aria = await this.snapshot();
    this.pending = { kind: "steps", caseId: testCase.id, reason };
    this.setPhase("waiting-steps");
    this.log("need-steps", {
      caseId: testCase.id,
      title: testCase.title,
      intent: testCase.intent ?? null,
      expect: testCase.expect ?? null,
      reason,
      aria,
    });
    while (testCase.steps.length === 0 && !this.interrupted()) {
      await this.signal();
    }
    this.pending = null;
  }

  private async waitForApproval(
    testCase: TestCase | null,
    step: Step,
  ): Promise<boolean> {
    const js = "js" in step.do ? step.do.js : "";
    const ids = { caseId: testCase?.id ?? null, stepId: step.id };
    this.pending = { kind: "approval", ...ids, js, why: step.why };
    this.approval = null;
    this.setPhase("waiting-approval");
    this.log("need-approval", { ...ids, why: step.why, js });
    while (!this.approval && !this.interrupted()) await this.signal();
    const allowed = this.approval === "allow";
    this.approval = null;
    this.pending = null;
    this.log(allowed ? "step-allowed" : "step-denied", ids);
    return allowed;
  }

  private async judge(testCase: TestCase): Promise<CaseOutcome | null> {
    const expectation = testCase.expect;
    if (expectation?.js) {
      try {
        await this.executor.check(expectation.js);
        return { verdict: "pass" };
      } catch (error) {
        return { verdict: "fail", note: describe(error) };
      }
    }
    if (expectation?.text) {
      this.pending = { kind: "verdict", caseId: testCase.id, text: expectation.text };
      this.humanVerdict = null;
      this.setPhase("waiting-verdict");
      this.log("need-verdict", {
        caseId: testCase.id,
        title: testCase.title,
        expect: expectation.text,
      });
      while (!this.humanVerdict && !this.interrupted()) await this.signal();
      const verdict = this.humanVerdict;
      this.humanVerdict = null;
      this.pending = null;
      return verdict;
    }
    return { verdict: "pass", note: "No expectation; every step ran." };
  }

  private async snapshot(): Promise<string> {
    try {
      return await this.executor.snapshot();
    } catch (error) {
      return `(aria snapshot unavailable: ${describe(error)})`;
    }
  }

  private interrupted(): boolean {
    return this.stopRequested || this.skipCaseRequested;
  }

  private currentCase(): TestCase | undefined {
    return this.caseIndex >= 0 ? this.plan.cases[this.caseIndex] : undefined;
  }

  private currentSteps(): Step[] {
    if (this.caseIndex < 0) return this.plan.setup ?? [];
    return this.currentCase()?.steps ?? [];
  }

  private findCase(id: string): TestCase | undefined {
    return this.plan.cases.find((testCase) => testCase.id === id);
  }

  private setPhase(phase: Phase): void {
    this.phase = phase;
    void this.render();
  }

  private render(): Promise<void> {
    const state = this.state();
    this.renderChain = this.renderChain
      .then(() => this.executor.render(state))
      .catch(() => undefined);
    return this.renderChain;
  }

  private log(type: string, payload: Record<string, unknown> = {}): void {
    this.journal.append(type, payload);
  }

  private signal(timeoutMs?: number): Promise<void> {
    return new Promise((resolve) => {
      let timer: ReturnType<typeof setTimeout> | undefined;
      const done = (): void => {
        if (timer) clearTimeout(timer);
        resolve();
      };
      this.wakers.push(done);
      if (timeoutMs !== undefined) {
        timer = setTimeout(done, Math.max(0, timeoutMs));
      }
    });
  }

  private wake(): void {
    const wakers = this.wakers;
    this.wakers = [];
    for (const wake of wakers) wake();
  }
}

