import fs from "node:fs";
import http from "node:http";
import net from "node:net";
import os from "node:os";
import path from "node:path";

// The brain's channel into a running rehearsal: a Unix socket in a 0700
// directory, never a TCP port, with a fixed command list and no Node-side
// eval. approve and deny are deliberately absent, so only the HUD (the person
// at the screen) can let model-written js run.
export const SOCKET_COMMANDS = new Set([
  "status",
  "events",
  "pause",
  "resume",
  "next",
  "mode",
  "speed",
  "dwell",
  "skip-step",
  "skip-case",
  "retry",
  "steps",
  "add-case",
  "verdict",
  "note",
  "query",
  "aria",
  "text",
  "screenshot",
  "console",
  "stop",
]);

const MAX_BODY_BYTES = 1_000_000;

const currentUid = (): number =>
  typeof process.getuid === "function" ? process.getuid() : 0;

export const defaultSocketPath = (): string =>
  process.env.DG_REHEARSE_SOCKET ||
  path.join(os.tmpdir(), `dg-rehearse-${currentUid()}`, "rehearse.sock");

const prepareSocketDir = (dir: string): void => {
  const uid = currentUid();
  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  const stat = fs.lstatSync(dir);
  if (!stat.isDirectory() || stat.uid !== uid) {
    throw new Error(`Refusing a socket dir not owned by uid ${uid}: ${dir}`);
  }
  fs.chmodSync(dir, 0o700);
};

const isListening = (socketPath: string): Promise<boolean> =>
  new Promise((resolve) => {
    const probe = net.connect(socketPath);
    probe.once("connect", () => {
      probe.destroy();
      resolve(true);
    });
    probe.once("error", () => resolve(false));
  });

const readBody = (req: http.IncomingMessage): Promise<string> =>
  new Promise((resolve, reject) => {
    let size = 0;
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error("Request body too large."));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });

export type ControlHandler = (
  cmd: string,
  args: Record<string, unknown>,
) => Promise<unknown>;

export type ControlServer = {
  socketPath: string;
  close(): Promise<void>;
};

export const startControlServer = async ({
  socketPath,
  handle,
}: {
  socketPath: string;
  handle: ControlHandler;
}): Promise<ControlServer> => {
  prepareSocketDir(path.dirname(socketPath));
  if (fs.existsSync(socketPath)) {
    if (await isListening(socketPath)) {
      throw new Error(
        `Another rehearsal is already listening on ${socketPath}. Stop it first.`,
      );
    }
    fs.rmSync(socketPath, { force: true });
  }

  const server = http.createServer((req, res) => {
    const respond = (status: number, payload: unknown): void => {
      res.writeHead(status, { "content-type": "application/json" });
      res.end(JSON.stringify(payload));
    };
    if (
      req.method !== "POST" ||
      !req.headers["content-type"]?.startsWith("application/json")
    ) {
      respond(415, { ok: false, error: "POST application/json only." });
      return;
    }
    readBody(req)
      .then(async (raw) => {
        const body: unknown = JSON.parse(raw || "{}");
        if (typeof body !== "object" || body === null || Array.isArray(body)) {
          throw new Error('Send a JSON object such as {"cmd":"status"}.');
        }
        const { cmd, ...args } = body as Record<string, unknown>;
        if (typeof cmd !== "string" || !SOCKET_COMMANDS.has(cmd)) {
          throw new Error(`Unknown or disallowed command: ${String(cmd)}.`);
        }
        const value = await handle(cmd, args);
        respond(200, { ok: true, value: value ?? null });
      })
      .catch((error: unknown) => {
        respond(400, {
          ok: false,
          error: error instanceof Error ? error.message : String(error),
        });
      });
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(socketPath, () => {
      server.off("error", reject);
      resolve();
    });
  });
  fs.chmodSync(socketPath, 0o600);

  return {
    socketPath,
    close: () =>
      new Promise<void>((resolve) => {
        server.close(() => resolve());
        server.closeAllConnections();
        fs.rmSync(socketPath, { force: true });
      }),
  };
};

/**
 * Client for a running rehearsal's control socket. The brain (a Claude Code
 * session) calls this; you can too.
 *
 *   npx tsx /mnt/data/projects/dg-demo-videos/rehearse/ctl.ts <command> [json | -]
 *
 *   ctl status
 *   ctl events '{"since":0,"waitMs":20000}'
 *   ctl steps - < steps.json
 *
 * The socket defaults to $TMPDIR/dg-rehearse-<uid>/rehearse.sock; set
 * DG_REHEARSE_SOCKET to point elsewhere.
 */
import http from "node:http";
import { SOCKET_COMMANDS, defaultSocketPath } from "./control";

const usage = `Usage: ctl <command> [json | -]
Commands: ${[...SOCKET_COMMANDS].join(", ")}
Pass arguments as one JSON object, or "-" to read it from stdin.`;

const readStdin = (): Promise<string> =>
  new Promise((resolve, reject) => {
    let data = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk: string) => {
      data += chunk;
    });
    process.stdin.on("end", () => resolve(data));
    process.stdin.on("error", reject);
  });

const post = (
  socketPath: string,
  body: string,
): Promise<{ status: number; body: string }> =>
  new Promise((resolve, reject) => {
    const req = http.request(
      {
        socketPath,
        path: "/",
        method: "POST",
        headers: {
          "content-type": "application/json",
          "content-length": Buffer.byteLength(body),
        },
      },
      (res) => {
        let data = "";
        res.setEncoding("utf8");
        res.on("data", (chunk: string) => {
          data += chunk;
        });
        res.on("end", () => resolve({ status: res.statusCode ?? 0, body: data }));
      },
    );
    req.on("error", reject);
    req.end(body);
  });

const main = async (): Promise<void> => {
  const [cmd, raw] = process.argv.slice(2);
  if (!cmd || cmd === "--help" || cmd === "-h") {
    console.log(usage);
    process.exit(cmd ? 0 : 1);
  }
  const text = raw === "-" ? await readStdin() : raw;
  let args: Record<string, unknown> = {};
  if (text && text.trim()) {
    try {
      args = JSON.parse(text) as Record<string, unknown>;
    } catch (error) {
      console.error(`Arguments must be one JSON object: ${String(error)}`);
      process.exit(1);
    }
  }
  const socketPath = defaultSocketPath();
  let response: { status: number; body: string };
  try {
    response = await post(socketPath, JSON.stringify({ ...args, cmd }));
  } catch (error) {
    console.error(
      `No rehearsal is listening at ${socketPath} (${error instanceof Error ? error.message : String(error)}).`,
    );
    process.exit(2);
  }
  let pretty = response.body;
  try {
    pretty = JSON.stringify(JSON.parse(response.body), null, 2);
  } catch {
    // Not JSON; print as is.
  }
  process.stdout.write(`${pretty}\n`);
  process.exit(response.status === 200 ? 0 : 1);
};

void main();

import type { Frame } from "playwright";
import type { CommandResult } from "./machine";

export const HUD_BINDING = "__dgRehearseCall";

// What the person at the screen can do. This is the only path to approve,
// deny or give a final verdict.
export const HUD_COMMANDS = new Set([
  "hello",
  "pause",
  "resume",
  "next",
  "speed",
  "mode",
  "skip-step",
  "skip-case",
  "retry",
  "approve",
  "deny",
  "verdict",
  "note",
  "stop",
]);

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

export const makeHudHandler =
  ({
    nonce,
    isMainFrame,
    command,
  }: {
    nonce: string;
    isMainFrame: (frame: Frame) => boolean;
    command: (cmd: string, args: Record<string, unknown>) => CommandResult;
  }) =>
  async (source: { frame: Frame }, payload: unknown): Promise<CommandResult> => {
    if (!isMainFrame(source.frame)) {
      return { ok: false, error: "The HUD only answers the main frame." };
    }
    if (!isRecord(payload) || payload.nonce !== nonce) {
      return { ok: false, error: "Unknown caller." };
    }
    const cmd = typeof payload.cmd === "string" ? payload.cmd : "";
    if (!HUD_COMMANDS.has(cmd)) {
      return { ok: false, error: `The HUD can't send "${cmd}".` };
    }
    return command(cmd, isRecord(payload.args) ? payload.args : {});
  };

// The HUD lives in a closed shadow root, so page scripts and Playwright
// selectors can't reach its buttons, and it hides while a step runs so it
// never intercepts the test's own clicks. It captures the binding and the
// per-session nonce at document start, before any page script runs.
// Tests pass shadow: "open" so they can click it.
export const buildHudScript = (
  nonce: string,
  { shadow = "closed" }: { shadow?: "open" | "closed" } = {},
): string => `(() => {
  if (window.__dgHud) return;
  const NONCE = ${JSON.stringify(nonce)};
  const BINDING = ${JSON.stringify(HUD_BINDING)};
  const SPEEDS = [0.25, 0.5, 1, 1.5, 2, 3, 4];
  const MODES = ["auto", "step", "case"];
  let call = window[BINDING];
  const send = (cmd, args) => {
    if (typeof call !== "function") call = window[BINDING];
    if (typeof call !== "function") {
      return Promise.resolve({ ok: false, error: "The runner is not connected." });
    }
    return Promise.resolve(call({ nonce: NONCE, cmd, args: args || {} })).catch(
      (error) => ({ ok: false, error: String(error) }),
    );
  };

  const CSS = \`
    :host { all: initial; }
    .hud { box-sizing: border-box; width: 370px; padding: 10px 12px; border-radius: 10px;
      font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif; color: #eef1f6;
      background: rgba(17, 21, 29, .95); border: 1px solid rgba(255, 255, 255, .14);
      box-shadow: 0 8px 28px rgba(0, 0, 0, .4); }
    .row { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
    .badge { font: 600 10.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .06em;
      text-transform: uppercase; padding: 4px 6px; border-radius: 4px; background: #3a4150; }
    .badge.running { background: #2c62c9; }
    .badge.paused, .badge.waiting-next, .badge.dwell { background: #8a5a06; }
    .badge.step-failed { background: #c93a28; }
    .badge.waiting-steps, .badge.waiting-approval, .badge.waiting-verdict { background: #6f3fb8; }
    .badge.done, .badge.stopped { background: #15805a; }
    .case { flex: 1; min-width: 0; font-weight: 600; white-space: nowrap; overflow: hidden;
      text-overflow: ellipsis; }
    .step { color: #b9c1ce; margin: 5px 0 4px; }
    .src { font: 10px ui-monospace, Menlo, monospace; padding: 1px 5px; border-radius: 3px;
      background: #2d3340; color: #d6dbe4; margin-left: 4px; }
    .pending { margin: 6px 0; padding: 8px; border-radius: 6px; background: rgba(255, 255, 255, .06); }
    .pending:empty { display: none; }
    .pending p { margin: 0 0 6px; }
    pre { margin: 6px 0; max-height: 150px; overflow: auto; white-space: pre-wrap;
      word-break: break-word; font: 11px/1.45 ui-monospace, Menlo, monospace;
      background: #0a0d12; padding: 6px 7px; border-radius: 4px; }
    button { font: 600 12px system-ui, -apple-system, sans-serif; color: #eef1f6;
      background: #2d3340; border: 1px solid rgba(255, 255, 255, .13); border-radius: 6px;
      padding: 4px 8px; cursor: pointer; }
    button:hover { background: #3b4354; }
    button:focus-visible { outline: 2px solid #7da7ff; outline-offset: 1px; }
    button.go { background: #15805a; }
    button.no { background: #a33224; }
    button.hot { box-shadow: 0 0 0 2px #e7b04c; }
    .speed { min-width: 36px; text-align: center; font: 12px ui-monospace, Menlo, monospace; }
    .controls { margin-top: 6px; }
    input { box-sizing: border-box; width: 100%; margin-top: 8px; padding: 5px 7px;
      font: 12px system-ui, -apple-system, sans-serif; color: #eef1f6; background: #0a0d12;
      border: 1px solid rgba(255, 255, 255, .14); border-radius: 6px; }
    .muted { color: #9099a9; font-size: 12px; }
    .hud.collapsed .step, .hud.collapsed .pending, .hud.collapsed .controls,
    .hud.collapsed input { display: none; }
  \`;

  let state = null;
  let host = null;
  let parts = null;
  let collapsed = false;
  let stopArmed = 0;

  const button = (label, cmd, extra) => {
    const el = document.createElement("button");
    el.type = "button";
    el.textContent = label;
    el.dataset.cmd = cmd;
    if (extra && extra.className) el.className = extra.className;
    if (extra && extra.args) el.dataset.args = JSON.stringify(extra.args);
    return el;
  };

  const mount = () => {
    if (host && host.isConnected) return true;
    if (!document.body) return false;
    host = document.createElement("div");
    host.id = "__dg-rehearse-hud";
    host.style.cssText = "all:initial;position:fixed;right:16px;bottom:16px;z-index:2147483647;";
    const root = host.attachShadow({ mode: ${JSON.stringify(shadow)} });
    const style = document.createElement("style");
    style.textContent = CSS;
    const panel = document.createElement("div");
    panel.className = "hud";
    const head = document.createElement("div");
    head.className = "row";
    const badge = document.createElement("span");
    badge.className = "badge";
    const title = document.createElement("span");
    title.className = "case";
    const fold = button("–", "local:fold");
    head.append(badge, title, fold);
    const step = document.createElement("div");
    step.className = "step";
    const pending = document.createElement("div");
    pending.className = "pending";
    const controls = document.createElement("div");
    controls.className = "row controls";
    const toggle = button("Pause", "local:toggle");
    const next = button("Next", "next");
    const slower = button("−", "local:slower");
    const speed = document.createElement("span");
    speed.className = "speed";
    const faster = button("+", "local:faster");
    const mode = button("auto", "local:mode");
    const pass = button("✓ Pass", "verdict", { className: "go", args: { verdict: "pass" } });
    const fail = button("✗ Fail", "verdict", { className: "no", args: { verdict: "fail" } });
    const stop = button("Stop", "local:stop");
    controls.append(toggle, next, slower, speed, faster, mode, pass, fail, stop);
    const note = document.createElement("input");
    note.placeholder = "Note for this case, then Enter";
    note.setAttribute("aria-label", "Note for this case");
    for (const type of ["keydown", "keyup", "keypress"]) {
      note.addEventListener(type, (event) => event.stopPropagation());
    }
    note.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" || !note.value.trim()) return;
      const text = note.value.trim();
      note.value = "";
      send("note", { text });
    });
    panel.append(head, step, pending, controls, note);
    root.append(style, panel);
    root.addEventListener("click", (event) => {
      const target = event.target && event.target.closest ? event.target.closest("button") : null;
      if (!target) return;
      const cmd = target.dataset.cmd;
      const args = target.dataset.args ? JSON.parse(target.dataset.args) : {};
      if (cmd === "local:fold") { collapsed = !collapsed; paint(); return; }
      if (cmd === "local:toggle") { send(state && state.paused ? "resume" : "pause"); return; }
      if (cmd === "local:slower" || cmd === "local:faster") {
        const current = state ? state.speed : 1;
        const index = SPEEDS.findIndex((value) => value >= current);
        const at = index < 0 ? SPEEDS.length - 1 : index;
        const nextIndex = cmd === "local:faster" ? Math.min(SPEEDS.length - 1, at + 1) : Math.max(0, at - 1);
        send("speed", { speed: SPEEDS[nextIndex] });
        return;
      }
      if (cmd === "local:mode") {
        const current = state ? state.mode : "auto";
        send("mode", { mode: MODES[(MODES.indexOf(current) + 1) % MODES.length] });
        return;
      }
      if (cmd === "local:stop") {
        if (Date.now() < stopArmed) { stopArmed = 0; send("stop"); return; }
        stopArmed = Date.now() + 3000;
        paint();
        setTimeout(paint, 3100);
        return;
      }
      send(cmd, args);
    });
    document.body.appendChild(host);
    parts = { panel, badge, title, step, pending, toggle, next, speed, mode, pass, fail, stop };
    return true;
  };

  const text = (tag, value, className) => {
    const el = document.createElement(tag);
    el.textContent = value;
    if (className) el.className = className;
    return el;
  };

  const paintPending = (pending) => {
    const box = parts.pending;
    box.replaceChildren();
    if (!state) return;
    const p = state.pending;
    if (p && p.kind === "steps") {
      box.append(text("p", "The brain is working out steps for this case."));
      box.append(button("Skip case", "skip-case"));
    } else if (p && p.kind === "failure") {
      box.append(text("p", "This step failed:"));
      box.append(text("pre", p.error));
      const row = document.createElement("div");
      row.className = "row";
      row.append(button("Retry", "retry", { className: "go" }), button("Skip step", "skip-step"), button("Skip case", "skip-case"));
      box.append(row);
    } else if (p && p.kind === "approval") {
      box.append(text("p", "The brain wants to run this js: " + p.why));
      box.append(text("pre", p.js));
      const row = document.createElement("div");
      row.className = "row";
      row.append(
        button("Allow", "approve", { className: "go", args: { stepId: p.stepId } }),
        button("Deny", "deny", { className: "no", args: { stepId: p.stepId } }),
      );
      box.append(row);
    } else if (p && p.kind === "verdict") {
      box.append(text("p", "Check: " + p.text));
      if (p.proposal) {
        box.append(text("p", "Brain says " + p.proposal.verdict + (p.proposal.reason ? ": " + p.proposal.reason : "."), "muted"));
      }
    } else if (state.phase === "done") {
      const values = Object.values(state.results || {});
      const count = (v) => values.filter((x) => x === v).length;
      box.append(text("p", "All cases ran: " + count("pass") + " passed, " + count("fail") + " failed, " + count("skip") + " skipped."));
      box.append(text("p", "Add a case from chat, or press Stop to write the report.", "muted"));
    }
  };

  const paint = () => {
    if (!state || !mount()) return;
    host.style.display = state.executing ? "none" : "block";
    parts.panel.classList.toggle("collapsed", collapsed);
    parts.badge.className = "badge " + state.phase;
    parts.badge.textContent = state.paused && state.phase === "paused" ? "paused" : state.phase.replace("-", " ");
    const caseLabel = state.caseIndex < 0
      ? "Setup"
      : state.caseIndex >= state.caseCount
        ? "Plan finished"
        : "Case " + (state.caseIndex + 1) + "/" + state.caseCount + " · " + (state.caseTitle || "");
    parts.title.textContent = caseLabel;
    parts.step.replaceChildren();
    if (state.stepWhy && state.caseIndex < state.caseCount) {
      parts.step.append(document.createTextNode("Step " + (state.stepIndex + 1) + "/" + state.stepCount + " · " + state.stepWhy));
      if (state.stepSource && state.stepSource !== "plan") {
        parts.step.append(text("span", state.stepSource, "src"));
      }
    }
    paintPending();
    parts.toggle.textContent = state.paused ? "Resume" : "Pause";
    parts.speed.textContent = state.speed + "×";
    parts.mode.textContent = state.mode;
    const verdictHot = state.pending && state.pending.kind === "verdict";
    parts.pass.classList.toggle("hot", !!verdictHot);
    parts.fail.classList.toggle("hot", !!verdictHot);
    parts.stop.textContent = Date.now() < stopArmed ? "Stop?" : "Stop";
  };

  const render = (next) => {
    state = next;
    paint();
  };

  Object.defineProperty(window, "__dgHud", {
    value: Object.freeze({ render }),
    configurable: false,
    writable: false,
  });

  const boot = () => {
    if (!mount()) {
      requestAnimationFrame(boot);
      return;
    }
    send("hello").then((result) => {
      if (result && result.ok) render(result.value);
    });
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot, { once: true });
  } else {
    boot();
  }

  document.addEventListener(
    "keydown",
    (event) => {
      if (!event.ctrlKey || !event.altKey) return;
      if (event.code === "Space") {
        event.preventDefault();
        event.stopPropagation();
        send(state && state.paused ? "resume" : "pause");
      } else if (event.code === "Period") {
        event.preventDefault();
        event.stopPropagation();
        send("next");
      }
    },
    true,
  );
})();`;

