import type { JournalEvent } from "./journal";
import type { Plan, Step, TestCase, Verdict } from "./plan";

// The working plan already holds what the session learned: steps the brain
// or you added (denied ones removed, failed ones replaced in place) and cases
// added live. Baking stamps each case with its verdict and notes. It never
// touches the plan on disk; you review plan.proposed.json and move it.
export const bakePlan = ({
  working,
  events,
  session,
  results,
  notes,
}: {
  working: Plan;
  events: JournalEvent[];
  session: string;
  results: Record<string, Verdict>;
  notes: Record<string, string>;
}): Plan => {
  const baked = structuredClone(working);
  const at = new Date().toISOString();
  for (const testCase of baked.cases) {
    const verdict = results[testCase.id];
    if (verdict) {
      testCase.last = { verdict, at, session };
      if (notes[testCase.id]) testCase.last.note = notes[testCase.id];
    }
    const added = [
      ...events
        .filter((event) => event.type === "note" && event.caseId === testCase.id)
        .map((event) => `${session}: ${String(event.text)}`),
      ...events
        .filter(
          (event) =>
            event.type === "step-resolved" &&
            event.resolution === "skip" &&
            event.caseId === testCase.id,
        )
        .map(
          (event) =>
            `${session}: step ${String(event.stepId)} failed and was skipped`,
        ),
    ];
    if (added.length > 0) testCase.notes = [...(testCase.notes ?? []), ...added];
  }
  return baked;
};

const sourceLabel = (step: Step): string =>
  step.source === "you" ? "by you" : "by the brain";

const describeChanges = (original: Plan, baked: Plan, events: JournalEvent[]): string[] => {
  const lines: string[] = [];
  const before = new Map(original.cases.map((testCase) => [testCase.id, testCase]));
  for (const testCase of baked.cases) {
    const previous = before.get(testCase.id);
    if (!previous) {
      const added = events.find(
        (event) => event.type === "case-added" && event.caseId === testCase.id,
      );
      lines.push(
        `**${testCase.title}**: new case${added?.by === "you" ? ", asked for by you" : ""}`,
      );
      continue;
    }
    const oldIds = new Set(previous.steps.map((step) => step.id));
    const newSteps = testCase.steps.filter((step) => !oldIds.has(step.id));
    const keptIds = new Set(testCase.steps.map((step) => step.id));
    const removed = previous.steps.filter((step) => !keptIds.has(step.id));
    for (const step of newSteps) {
      lines.push(`**${testCase.title}**: added "${step.why}" (${sourceLabel(step)})`);
    }
    for (const step of removed) {
      lines.push(`**${testCase.title}**: replaced "${step.why}"`);
    }
  }
  const denied = events.filter((event) => event.type === "step-denied").length;
  if (denied > 0) {
    lines.push(`You denied ${denied} js step${denied === 1 ? "" : "s"} from the brain.`);
  }
  return lines;
};

const caseLine = (testCase: TestCase, verdict: Verdict | undefined, note?: string): string => {
  const box = verdict === "pass" ? "[x]" : "[ ]";
  const word =
    verdict === "pass"
      ? "pass"
      : verdict === "fail"
        ? "fail"
        : verdict === "skip"
          ? "skipped"
          : "not run";
  const detail = note && verdict !== "pass" ? `. ${note.split("\n")[0]}` : "";
  return `- ${box} **${testCase.title}**: ${word}${detail}`;
};

const details = (summary: string, body: string): string =>
  `<details><summary>${summary}</summary>\n\n${body}\n\n</details>`;

export const renderReport = ({
  original,
  baked,
  events,
  session,
  results,
  notes,
  graph,
  dist,
  consoleLines,
}: {
  original: Plan;
  baked: Plan;
  events: JournalEvent[];
  session: string;
  results: Record<string, Verdict>;
  notes: Record<string, string>;
  graph: string;
  dist: string | null;
  consoleLines: string[];
}): string => {
  const total = baked.cases.length;
  const passed = baked.cases.filter((testCase) => results[testCase.id] === "pass").length;
  const header = [
    `### Live rehearsal: ${baked.title ?? baked.name}`,
    "",
    [
      `\`${baked.name}\``,
      graph,
      dist ? `build \`${dist}\`` : "no extension",
      new Date().toISOString().slice(0, 10),
      `${passed}/${total} passed`,
    ].join(" · "),
    "",
  ];
  const cases = baked.cases.map((testCase) =>
    caseLine(testCase, results[testCase.id], notes[testCase.id]),
  );
  const sections: string[] = [];
  const changes = describeChanges(original, baked, events);
  if (changes.length > 0) {
    sections.push(
      details(
        "What the session changed in the plan",
        changes.map((line) => `- ${line}`).join("\n"),
      ),
    );
  }
  const noteEvents = events.filter((event) => event.type === "note");
  if (noteEvents.length > 0) {
    const titles = new Map(baked.cases.map((testCase) => [testCase.id, testCase.title]));
    sections.push(
      details(
        "Notes",
        noteEvents
          .map((event) => {
            const where = titles.get(String(event.caseId)) ?? "Session";
            return `- **${where}**: ${String(event.text)} (${event.by === "you" ? "you" : "brain"})`;
          })
          .join("\n"),
      ),
    );
  }
  if (consoleLines.length > 0) {
    sections.push(
      details(
        `Console errors (${consoleLines.length})`,
        ["```text", ...consoleLines.slice(0, 50), "```"].join("\n"),
      ),
    );
  }
  return [...header, ...cases, "", ...sections, "", `<sub>Session ${session}</sub>`, ""].join(
    "\n",
  );
};

/**
 * Live rehearsal: drive a test plan through the real app while you watch and
 * steer. Run it from discourse-graph/apps/roam (for its tsx and playwright):
 *
 *   npx tsx /mnt/data/projects/dg-demo-videos/rehearse/rehearse.ts --plan <file> [flags]
 *
 * Flags:
 *   --plan <file>       Required. JSON test plan (see rehearse/README.md).
 *   --dist <dir>        Extension dist folder (overrides target.dist).
 *   --no-extension      Skip the developer-extension load.
 *   --slot <1|2|3>      Playwright profile slot (default target.slot, else 3).
 *   --url <graph-url>   Override the slot's graph URL.
 *   --allow-dev-graph   Allow discourse-dev-graph; refused by default.
 *   --allow-login       Wait for a manual login if the profile is logged out.
 *   --mode <m>          auto (default), step or case.
 *   --speed <x>         0.25 to 4 (default 1).
 *   --dwell <ms>        Hold after each step so you can follow (default 1200).
 *   --dpr <n>           Device scale factor (default target.dpr, else 2).
 *   --no-cursor         Don't draw the cursor overlay.
 *   --out <dir>         Session folder root (default dg-demo-videos/output/rehearse).
 *   --timeout <ms>      Default step timeout (default 45000).
 *
 * The browser opens headed; i3 sends it to workspace 9. The brain talks to the
 * runner through rehearse/ctl.ts. Nothing ends until you press Stop on the
 * HUD or the brain sends stop.
 */
import crypto from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import type { BrowserContext, Page } from "playwright";
import {
  CURSOR_INIT_SCRIPT,
  buildPickerShimScript,
  loadDeveloperExtension,
  readFolderFiles,
  runAction,
} from "../recorder/recordDemo";
import {
  defaultChromium,
  getBooleanArg,
  getStringArg,
  graphNameFromRoamUrl,
  parseArgs,
  resolveSlotConfig,
  timestamp,
  waitForRoamReady,
} from "../../discourse-graph/apps/roam/scripts/playwright/roamSession";
import { bakePlan, renderReport } from "./bake";
import { defaultSocketPath, startControlServer, type ControlServer } from "./control";
import { HUD_BINDING, buildHudScript, makeHudHandler } from "./hud";
import { Journal } from "./journal";
import { MAX_SPEED, MIN_SPEED, Machine, type Executor, type Mode } from "./machine";
import { SCREENSHOT_NAME, loadPlan, savePlan } from "./plan";

const ARIA_LIMIT = 40_000;
const TEXT_LIMIT = 20_000;
const QUERY_LIMIT = 50_000;
const CONSOLE_LIMIT = 200;

const log = (message: string): void => console.log(`[rehearse] ${message}`);

const clip = (value: string, limit: number): string =>
  value.length > limit ? `${value.slice(0, limit)}\n… (${value.length - limit} more characters)` : value;

const numberArg = (value: string | undefined, fallback: number): number => {
  const parsed = Number(value);
  return value !== undefined && value !== "" && Number.isFinite(parsed) ? parsed : fallback;
};

const PROFILE_IN_USE =
  /processsingleton|profile.*(?:lock|in use)|singletonlock|already running|existing browser session/i;

const main = async (): Promise<void> => {
  const args = parseArgs(process.argv.slice(2));
  const planArg = getStringArg(args, "plan");
  if (!planArg) throw new Error("--plan <file> is required.");
  const planFile = path.resolve(planArg);
  const plan = await loadPlan(planFile);
  const original = structuredClone(plan);
  const target = plan.target ?? {};

  const mode = (getStringArg(args, "mode") || "auto") as Mode;
  if (!["auto", "step", "case"].includes(mode)) {
    throw new Error("--mode must be auto, step or case.");
  }
  const speed = numberArg(getStringArg(args, "speed"), 1);
  if (speed < MIN_SPEED || speed > MAX_SPEED) {
    throw new Error(`--speed must be between ${MIN_SPEED} and ${MAX_SPEED}.`);
  }
  const dwellMs = numberArg(getStringArg(args, "dwell"), 1200);
  const timeout = numberArg(getStringArg(args, "timeout"), 45_000);
  const viewport = target.viewport ?? { width: 1280, height: 720 };
  const dpr = numberArg(getStringArg(args, "dpr"), target.dpr ?? 2);
  const cursor = !getBooleanArg(args, "no-cursor");

  const skipExtension = getBooleanArg(args, "no-extension");
  const distArg = getStringArg(args, "dist") || target.dist;
  if (!skipExtension && !distArg) {
    throw new Error("Pass --dist <dir>, set target.dist in the plan, or pass --no-extension.");
  }
  const distDir = skipExtension || !distArg ? null : path.resolve(distArg);
  const distFiles = distDir ? await readFolderFiles(distDir) : null;

  const slotConfig = resolveSlotConfig({
    slot: getStringArg(args, "slot") || target.slot || "3",
    requireCredentials: false,
    graphUrl: getStringArg(args, "url") || target.url,
  });
  const graph = graphNameFromRoamUrl(slotConfig.graphUrl);
  if (graph === "discourse-dev-graph" && !getBooleanArg(args, "allow-dev-graph")) {
    throw new Error(
      "This rehearsal would run on discourse-dev-graph. Rehearsals write to the graph, so they default to test-3-graph (slot 3). Pass --allow-dev-graph to override.",
    );
  }

  const outRoot = path.resolve(
    getStringArg(args, "out") || path.join(__dirname, "..", "output", "rehearse"),
  );
  const session = `${plan.name}-${timestamp()}`;
  const sessionDir = path.join(outRoot, session);
  const videoDir = path.join(sessionDir, "video");
  await fs.mkdir(videoDir, { recursive: true });
  const journal = new Journal(path.join(sessionDir, "journal.jsonl"));
  log(`Session: ${sessionDir}`);
  log(`Graph: ${graph} (slot ${slotConfig.slot}), mode ${mode}, speed ${speed}×`);

  const nonce = crypto.randomBytes(16).toString("hex");
  const consoleAll: string[] = [];
  const consoleUnread: string[] = [];
  const recordConsole = (line: string): void => {
    for (const list of [consoleAll, consoleUnread]) {
      list.push(line.slice(0, 1000));
      if (list.length > CONSOLE_LIMIT) list.shift();
    }
  };

  let context: BrowserContext;
  try {
    context = await defaultChromium.launchPersistentContext(slotConfig.profileDir, {
      headless: false,
      viewport,
      deviceScaleFactor: dpr,
      recordVideo: {
        dir: videoDir,
        size: { width: viewport.width * dpr, height: viewport.height * dpr },
      },
      args: [
        "--disable-features=LocalNetworkAccessChecks",
        `--force-device-scale-factor=${dpr}`,
        "--hide-crash-restore-bubble",
      ],
    });
  } catch (error) {
    if (PROFILE_IN_USE.test(String(error))) {
      throw new Error(
        `Profile slot ${slotConfig.slot} is in use by another session. Wait for it to finish, or pick another slot with --slot.`,
      );
    }
    throw error;
  }

  let page: Page | null = null;
  let machine: Machine | null = null;
  let server: ControlServer | null = null;
  try {
    await context.exposeBinding(
      HUD_BINDING,
      makeHudHandler({
        nonce,
        isMainFrame: (frame) => page !== null && frame === page.mainFrame(),
        command: (cmd, commandArgs) =>
          machine
            ? machine.command("hud", cmd, commandArgs)
            : { ok: false, error: "The runner is still starting." },
      }),
    );
    if (distDir && distFiles) {
      await context.addInitScript(buildPickerShimScript(path.basename(distDir), distFiles));
    }
    if (cursor) await context.addInitScript(CURSOR_INIT_SCRIPT);
    await context.addInitScript(buildHudScript(nonce));

    const livePage = context.pages()[0] ?? (await context.newPage());
    page = livePage;
    for (const extra of context.pages()) {
      if (extra !== livePage) await extra.close().catch(() => undefined);
    }
    livePage.on("console", (message) => {
      if (message.type() === "error") recordConsole(`[console.error] ${message.text()}`);
    });
    livePage.on("pageerror", (error) => recordConsole(`[pageerror] ${error.message}`));

    await livePage.goto(slotConfig.graphUrl, { waitUntil: "domcontentloaded" });
    await livePage
      .waitForSelector(
        '.roam-app, .roam-body, input[placeholder="Find or Create Page"], input[type="password"]',
        { timeout },
      )
      .catch(() => undefined);
    await waitForRoamReady({
      page: livePage,
      slotConfig,
      headless: false,
      allowInteractiveLogin: getBooleanArg(args, "allow-login"),
      timeout,
    });
    log("Roam is ready.");
    if (distDir) await loadDeveloperExtension({ page: livePage, distDir, timeout });

    const executor: Executor = {
      run: (action) =>
        runAction({ page: livePage, action, timeout, outDir: sessionDir, cursor }),
      check: async (js) => {
        await livePage.evaluate(js);
      },
      snapshot: async () =>
        clip(await livePage.locator("body").ariaSnapshot({ timeout: 5000 }), ARIA_LIMIT),
      render: async (state) => {
        await livePage.evaluate(
          `window.__dgHud && window.__dgHud.render(${JSON.stringify(state)})`,
        );
      },
    };

    const writeOutputs = async (): Promise<{ reportPath: string; proposedPath: string }> => {
      const live = machine as Machine;
      const events = journal.all();
      const baked = bakePlan({
        working: plan,
        events,
        session,
        results: live.results,
        notes: live.notes,
      });
      const proposedPath = path.join(sessionDir, "plan.proposed.json");
      await savePlan(proposedPath, baked);
      const reportPath = path.join(sessionDir, "report.md");
      await fs.writeFile(
        reportPath,
        renderReport({
          original,
          baked,
          events,
          session,
          results: live.results,
          notes: live.notes,
          graph,
          dist: distDir ? path.basename(distDir) : null,
          consoleLines: consoleAll,
        }),
      );
      return { reportPath, proposedPath };
    };

    machine = new Machine({
      plan,
      journal,
      executor,
      mode,
      speed,
      dwellMs,
      origin: new URL(slotConfig.graphUrl).origin,
      stayOpen: true,
      onIdle: async () => {
        const { reportPath } = await writeOutputs();
        log(`Every case has a verdict. Interim report: ${reportPath}`);
      },
    });
    const live = machine;

    server = await startControlServer({
      socketPath: defaultSocketPath(),
      handle: async (cmd, commandArgs) => {
        switch (cmd) {
          case "events": {
            const since = numberArg(String(commandArgs.since ?? ""), 0);
            const waitMs = Math.min(Math.max(numberArg(String(commandArgs.waitMs ?? ""), 0), 0), 30_000);
            const events = await journal.wait(since, waitMs);
            return { events, lastSeq: journal.lastSeq };
          }
          case "query": {
            if (typeof commandArgs.q !== "string" || !commandArgs.q.trim()) {
              throw new Error('query needs "q", a Datalog query string.');
            }
            const result = await livePage.evaluate(
              `JSON.stringify(window.roamAlphaAPI.q(${JSON.stringify(commandArgs.q)}))`,
            );
            return clip(String(result), QUERY_LIMIT);
          }
          case "aria": {
            const selector =
              typeof commandArgs.selector === "string" && commandArgs.selector
                ? commandArgs.selector
                : "body";
            return clip(
              await livePage.locator(selector).first().ariaSnapshot({ timeout: 5000 }),
              ARIA_LIMIT,
            );
          }
          case "text": {
            if (typeof commandArgs.selector !== "string" || !commandArgs.selector) {
              throw new Error('text needs a "selector".');
            }
            const texts = await livePage.locator(commandArgs.selector).allInnerTexts();
            return clip(texts.slice(0, 50).join("\n---\n"), TEXT_LIMIT);
          }
          case "screenshot": {
            const name = typeof commandArgs.name === "string" ? commandArgs.name : "";
            if (!SCREENSHOT_NAME.test(name)) {
              throw new Error("screenshot needs a file name with no slashes.");
            }
            const file = path.join(sessionDir, name.endsWith(".png") ? name : `${name}.png`);
            await livePage.screenshot({ path: file });
            return file;
          }
          case "console":
            return consoleUnread.splice(0, consoleUnread.length);
          default: {
            const result = live.command("socket", cmd, commandArgs);
            if (!result.ok) throw new Error(result.error);
            return result.value;
          }
        }
      },
    });

    const requestStop = (): void => {
      log("Stopping.");
      live.stop();
    };
    process.once("SIGINT", requestStop);
    process.once("SIGTERM", requestStop);

    log(`REHEARSE READY ${server.socketPath}`);
    await live.run();
    const { reportPath, proposedPath } = await writeOutputs();
    log(`Report: ${reportPath}`);
    log(`Proposed plan: ${proposedPath}`);
    log(`Review it with: diff -u ${planFile} ${proposedPath}`);
  } finally {
    if (server) await server.close().catch(() => undefined);
    const video = page?.video() ?? null;
    if (page) await page.close().catch(() => undefined);
    await context.close().catch(() => undefined);
    const rawVideo = video ? await video.path().catch(() => null) : null;
    if (rawVideo) {
      await fs
        .rename(rawVideo, path.join(sessionDir, "session.webm"))
        .then(() => log(`Footage: ${path.join(sessionDir, "session.webm")}`))
        .catch(() => undefined);
    }
    await fs.rm(videoDir, { recursive: true, force: true }).catch(() => undefined);
  }
};

if (require.main === module) {
  main().catch((error: unknown) => {
    console.error(error instanceof Error ? error.stack || error.message : String(error));
    process.exit(1);
  });
}

import assert from "node:assert/strict";
import test from "node:test";
import type { Action } from "../../recorder/recordDemo";
import { Journal, type JournalEvent } from "../journal";
import {
  Machine,
  scaleAction,
  type Executor,
  type MachineOptions,
  type MachineState,
} from "../machine";
import { validatePlan } from "../plan";

class FakeExecutor implements Executor {
  actions: Action[] = [];
  checks: string[] = [];
  failures = 0;
  states: MachineState[] = [];

  async run(action: Action): Promise<void> {
    this.actions.push(action);
    if (this.failures > 0) {
      this.failures -= 1;
      throw new Error("locator.click: Timeout 45000ms exceeded.");
    }
  }

  async check(js: string): Promise<void> {
    this.checks.push(js);
    if (js.includes("FAIL")) throw new Error("Expected 2 rows, saw 1");
  }

  async snapshot(): Promise<string> {
    return "- main: fake page";
  }

  async render(state: MachineState): Promise<void> {
    this.states.push(state);
  }
}

const setup = (
  rawPlan: unknown,
  options: Partial<Omit<MachineOptions, "plan" | "journal" | "executor">> = {},
) => {
  const journal = new Journal(null);
  const executor = new FakeExecutor();
  const machine = new Machine({
    plan: validatePlan(rawPlan),
    journal,
    executor,
    dwellMs: 0,
    ...options,
  });
  return { journal, executor, machine };
};

const waitForEvent = async (
  journal: Journal,
  type: string,
  nth = 1,
  timeoutMs = 2000,
): Promise<JournalEvent> => {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const matches = journal.all().filter((event) => event.type === type);
    if (matches.length >= nth) return matches[nth - 1];
    const left = deadline - Date.now();
    if (left <= 0) {
      throw new Error(
        `No "${type}" event within ${timeoutMs} ms. Saw: ${journal
          .all()
          .map((event) => event.type)
          .join(", ")}`,
      );
    }
    await journal.wait(journal.lastSeq, left);
  }
};

const delay = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

test("plan steps run in order and js expectations decide the verdict", async () => {
  const { executor, machine } = setup({
    name: "t",
    cases: [
      {
        id: "a",
        title: "A",
        steps: [
          { do: { click: "#one" }, why: "open" },
          { do: { press: "Enter" }, why: "confirm" },
        ],
        expect: { js: "1" },
      },
      {
        id: "b",
        title: "B",
        steps: [{ do: { click: "#two" }, why: "open" }],
        expect: { js: "FAIL" },
      },
    ],
  });
  await machine.run();
  assert.deepEqual(executor.actions, [
    { click: "#one" },
    { press: "Enter" },
    { click: "#two" },
  ]);
  assert.deepEqual(machine.results, { a: "pass", b: "fail" });
  assert.match(machine.notes.b, /Expected 2 rows/);
});

test("a case with only an intent waits for the brain's steps", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", intent: "open the settings" }],
  });
  const running = machine.run();
  const need = await waitForEvent(journal, "need-steps");
  assert.equal(need.aria, "- main: fake page");
  assert.equal(machine.state().phase, "waiting-steps");
  const result = machine.command("socket", "steps", {
    steps: [{ do: { click: "text=Settings" }, why: "open the settings" }],
  });
  assert.equal(result.ok, true);
  await running;
  assert.deepEqual(executor.actions, [{ click: "text=Settings" }]);
  assert.equal(machine.plan.cases[0].steps[0].source, "model");
  assert.deepEqual(machine.results, { a: "pass" });
});

test("js from the socket waits for the HUD, and the socket can't approve it", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", intent: "seed a page" }],
  });
  const running = machine.run();
  await waitForEvent(journal, "need-steps");
  machine.command("socket", "steps", {
    steps: [{ do: { js: "window.seeded = true" }, why: "seed the page" }],
  });
  const need = await waitForEvent(journal, "need-approval");
  const stepId = String(need.stepId);
  const fromSocket = machine.command("socket", "approve", { stepId });
  assert.equal(fromSocket.ok, false);
  assert.equal(executor.actions.length, 0);
  assert.equal(machine.command("hud", "approve", { stepId: "nope" }).ok, false);
  assert.equal(machine.command("hud", "approve", { stepId }).ok, true);
  await running;
  assert.deepEqual(executor.actions, [{ js: "window.seeded = true" }]);
  assert.equal(machine.plan.cases[0].steps[0].approved, true);
});

test("a denied step never runs and leaves the working plan", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", intent: "clean up" }],
  });
  const running = machine.run();
  await waitForEvent(journal, "need-steps");
  machine.command("socket", "steps", {
    steps: [
      { do: { js: "deleteEverything()" }, why: "clean up" },
      { do: { click: "#ok" }, why: "confirm" },
    ],
  });
  const need = await waitForEvent(journal, "need-approval");
