test("plans and actions with mistakes are refused with the reason", () => {
  assert.throws(() => validatePlan({ name: "x", cases: [] }), /at least one case/);
  assert.throws(
    () => validatePlan({ name: "x", cases: [{ title: "No way in" }] }),
    /steps, or an "intent"/,
  );
  assert.throws(
    () =>
      validatePlan({
        name: "x",
        cases: [
          { id: "a", title: "A", intent: "x" },
          { id: "a", title: "B", intent: "y" },
        ],
      }),
    /duplicate case id/,
  );
  assert.throws(
    () =>
      validatePlan({
        name: "x",
        cases: [{ title: "A", steps: [{ do: { click: "#x" } }] }],
      }),
    /needs a one-line "why"/,
  );
  assert.throws(() => validateAction({ tap: "#x" }, "step"), /unknown action "tap"/);
  assert.throws(
    () => validateAction({ click: "#x", press: "Enter" }, "step"),
    /exactly one key/,
  );
  assert.throws(
    () => validateAction({ screenshot: "../../etc/evil.png" }, "step"),
    /no slashes/,
  );
  assert.throws(() => validateAction({ pause: 600 }, "step"), /0 to 60/);
});

test("bake stamps verdicts and notes, and the report lists what changed", () => {
  const original = validatePlan({
    name: "eng-2348",
    title: "Stored Relations warning",
    cases: [
      { id: "a", title: "Share shows the warning", intent: "open Share with stored relations off" },
      { id: "b", title: "Import shows the warning", steps: [{ do: { click: "#import" }, why: "open import" }] },
    ],
  });
  const working = structuredClone(original);
  working.cases[0].steps.push({
    id: "s1",
    do: { command_palette: "DG: Share" },
    why: "open Share from the palette",
    source: "model",
  });
  const journal = new Journal(null);
  journal.append("note", { caseId: "a", text: "copy reads well", by: "you" });
  journal.append("step-denied", { caseId: "b", stepId: "s9" });
  const results = { a: "pass", b: "fail" } as const;
  const notes = { b: "no warning shown" };
  const baked = bakePlan({
    working,
    events: journal.all(),
    session: "eng-2348-test",
    results,
    notes,
  });
  assert.equal(baked.cases[0].last?.verdict, "pass");
  assert.deepEqual(baked.cases[0].notes, ["eng-2348-test: copy reads well"]);
  assert.equal(baked.cases[1].last?.note, "no warning shown");
  assert.equal(original.cases[0].steps.length, 0);

  const report = renderReport({
    original,
    baked,
    events: journal.all(),
    session: "eng-2348-test",
    results,
    notes,
    graph: "test-3-graph",
    dist: "dg-test-eng-2348",
    consoleLines: ["[pageerror] boom"],
  });
  assert.match(report, /### Live rehearsal: Stored Relations warning/);
  assert.match(report, /1\/2 passed/);
  assert.match(report, /- \[x\] \*\*Share shows the warning\*\*: pass/);
  assert.match(report, /- \[ \] \*\*Import shows the warning\*\*: fail\. no warning shown/);
  assert.match(report, /added "open Share from the palette" \(by the brain\)/);
  assert.match(report, /You denied 1 js step from the brain\./);
  assert.match(report, /Console errors \(1\)/);
});

import assert from "node:assert/strict";
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import { startControlServer } from "../control";

const post = (
  socketPath: string,
  body: unknown,
): Promise<{ status: number; json: Record<string, unknown> }> =>
  new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    const req = http.request(
      {
        socketPath,
        path: "/",
        method: "POST",
        headers: { "content-type": "application/json" },
      },
      (res) => {
        let data = "";
        res.setEncoding("utf8");
        res.on("data", (chunk: string) => {
          data += chunk;
        });
        res.on("end", () =>
          resolve({ status: res.statusCode ?? 0, json: JSON.parse(data) }),
        );
      },
    );
    req.on("error", reject);
    req.end(payload);
  });

test("the socket answers allowlisted commands and refuses the rest", async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "rehearse-control-"));
  const socketPath = path.join(dir, "sock", "rehearse.sock");
  const seen: string[] = [];
  const server = await startControlServer({
    socketPath,
    handle: async (cmd, args) => {
      seen.push(cmd);
      return { cmd, args };
    },
  });
  try {
    assert.equal(fs.statSync(path.dirname(socketPath)).mode & 0o777, 0o700);
    assert.equal(fs.statSync(socketPath).mode & 0o777, 0o600);

    const status = await post(socketPath, { cmd: "status" });
    assert.equal(status.status, 200);
    assert.deepEqual(status.json, { ok: true, value: { cmd: "status", args: {} } });

    const approve = await post(socketPath, { cmd: "approve", stepId: "s1" });
    assert.equal(approve.status, 400);
    assert.match(String(approve.json.error), /disallowed/);

    const evaluate = await post(socketPath, { cmd: "eval", code: "process.exit()" });
    assert.equal(evaluate.status, 400);
    assert.deepEqual(seen, ["status"]);

    await assert.rejects(
      startControlServer({ socketPath, handle: async () => null }),
      /already listening/,
    );
  } finally {
    await server.close();
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

