test("the HUD reaches the runner only with the session nonce", async () => {
  const browser = await defaultChromium.launch({ headless: true });
  try {
    const context = await browser.newContext();
    const calls: Array<{ cmd: string; args: Record<string, unknown> }> = [];
    const nonce = "test-nonce";
    let mainFrame: unknown = null;
    await context.exposeBinding(
      HUD_BINDING,
      makeHudHandler({
        nonce,
        isMainFrame: (frame) => frame === mainFrame,
        command: (cmd, args) => {
          calls.push({ cmd, args });
          return { ok: true, value: baseState };
        },
      }),
    );
    await context.addInitScript(buildHudScript(nonce, { shadow: "open" }));
    const page = await context.newPage();
    mainFrame = page.mainFrame();
    await page.route("http://hud.test/", (route) =>
      route.fulfill({
        contentType: "text/html",
        body: "<!doctype html><html><body><main><p>Graph</p></main></body></html>",
      }),
    );
    await page.goto("http://hud.test/");
    await page.waitForSelector("#__dg-rehearse-hud");
    await page.getByRole("button", { name: "Allow" }).waitFor();
    assert.equal(calls[0]?.cmd, "hello");

    await page.getByRole("button", { name: "Allow" }).click();
    assert.deepEqual(calls.at(-1), { cmd: "approve", args: { stepId: "s1" } });

    const forged = await page.evaluate(
      `window.${HUD_BINDING}({ cmd: "approve", args: { stepId: "s1" } })`,
    );
    assert.deepEqual(forged, { ok: false, error: "Unknown caller." });
    assert.equal(calls.filter((call) => call.cmd === "approve").length, 1);

    await page.keyboard.press("Control+Alt+Space");
    assert.equal(calls.at(-1)?.cmd, "pause");

    await page.evaluate(
      `window.__dgHud.render(${JSON.stringify({ ...baseState, executing: true, pending: null })})`,
    );
    const display = await page.evaluate(
      `getComputedStyle(document.getElementById("__dg-rehearse-hud")).display`,
    );
    assert.equal(display, "none");
  } finally {
    await browser.close();
  }
});

test("the production HUD is out of reach of page selectors", async () => {
  const browser = await defaultChromium.launch({ headless: true });
  try {
    const context = await browser.newContext();
    await context.exposeBinding(HUD_BINDING, async () => ({ ok: true, value: baseState }));
    await context.addInitScript(buildHudScript("n"));
    const page = await context.newPage();
    await page.route("http://hud.test/", (route) =>
      route.fulfill({ contentType: "text/html", body: "<!doctype html><body><p>x</p></body>" }),
    );
    await page.goto("http://hud.test/");
    await page.waitForSelector("#__dg-rehearse-hud", { state: "attached" });
    await page.waitForTimeout(200);
    assert.equal(await page.getByRole("button", { name: "Allow" }).count(), 0);
    const shadowRoot = await page.evaluate(
      `document.getElementById("__dg-rehearse-hud").shadowRoot === null`,
    );
    assert.equal(shadowRoot, true);
  } finally {
    await browser.close();
  }
});

